#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Analyze trajectory tracking error CSV generated by trajectory_logger.py."""

import argparse
import csv
import json
import math
import os
import statistics
from datetime import datetime


def f(row, key):
    value = row.get(key, "")
    if value == "":
        return None
    return float(value)


def percentile(values, pct):
    if not values:
        return None
    data = sorted(values)
    if len(data) == 1:
        return data[0]
    rank = (len(data) - 1) * pct / 100.0
    low = int(math.floor(rank))
    high = int(math.ceil(rank))
    if low == high:
        return data[low]
    return data[low] * (high - rank) + data[high] * (rank - low)


def stats(values):
    if not values:
        return {
            "count": 0, "mean": None, "median": None, "rmse": None,
            "p90": None, "p95": None, "max": None,
        }
    return {
        "count": len(values),
        "mean": statistics.mean(values),
        "median": statistics.median(values),
        "rmse": math.sqrt(statistics.mean([v * v for v in values])),
        "p90": percentile(values, 90),
        "p95": percentile(values, 95),
        "max": max(values),
    }


def read_rows(path):
    rows = []
    with open(path, "r") as fp:
        reader = csv.DictReader(fp)
        for row in reader:
            rows.append(row)
    return rows


def write_summary(summary, out_dir, base):
    json_path = os.path.join(out_dir, base + "_summary.json")
    txt_path = os.path.join(out_dir, base + "_summary.txt")
    with open(json_path, "w") as fp:
        json.dump(summary, fp, indent=2, sort_keys=True)
    with open(txt_path, "w") as fp:
        fp.write("Trajectory Tracking Analysis\n")
        fp.write("source: %s\n" % summary["source_csv"])
        fp.write("generated_at: %s\n\n" % summary["generated_at"])
        fp.write("samples_total: %d\n" % summary["samples_total"])
        fp.write("samples_with_desired: %d\n" % summary["samples_with_desired"])
        fp.write("duration_s: %.3f\n" % summary["duration_s"])
        fp.write("actual_path_length_m: %.3f\n" % summary["actual_path_length_m"])
        fp.write("desired_path_length_m: %.3f\n\n" % summary["desired_path_length_m"])
        for name in ["error_3d", "error_xy", "abs_error_z", "cmd_age"]:
            fp.write("[%s]\n" % name)
            for key, value in summary[name].items():
                fp.write("%s: %s\n" % (key, "nan" if value is None else "%.6f" % value))
            fp.write("\n")
    return json_path, txt_path


def path_length(points):
    total = 0.0
    prev = None
    for p in points:
        if prev is not None:
            total += math.sqrt(sum((p[i] - prev[i]) ** 2 for i in range(3)))
        prev = p
    return total


def make_plots(rows, out_dir, base):
    try:
        os.environ.setdefault("MPLCONFIGDIR", "/tmp/matplotlib-cache")
        if not os.path.isdir(os.environ["MPLCONFIGDIR"]):
            os.makedirs(os.environ["MPLCONFIGDIR"])
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
    except Exception as exc:
        return None, "matplotlib unavailable: %s" % exc

    t = []
    actual = []
    desired = []
    e3d = []
    exy = []
    ez_abs = []
    for row in rows:
        tr = f(row, "time_rel")
        ax = f(row, "actual_x"); ay = f(row, "actual_y"); az = f(row, "actual_z")
        dx = f(row, "desired_x"); dy = f(row, "desired_y"); dz = f(row, "desired_z")
        e3 = f(row, "error_3d"); ex = f(row, "error_xy"); ez = f(row, "error_z")
        if tr is None or ax is None or ay is None or az is None:
            continue
        actual.append((ax, ay, az))
        if dx is not None and dy is not None and dz is not None:
            t.append(tr)
            desired.append((dx, dy, dz))
            if e3 is not None:
                e3d.append(e3)
            if ex is not None:
                exy.append(ex)
            if ez is not None:
                ez_abs.append(abs(ez))

    if not actual:
        return None, "no actual trajectory samples"

    plot_path = os.path.join(out_dir, base + "_plots.png")
    fig, axes = plt.subplots(2, 2, figsize=(12, 9))

    axes[0][0].plot([p[0] for p in actual], [p[1] for p in actual], label="actual", linewidth=1.5)
    if desired:
        axes[0][0].plot([p[0] for p in desired], [p[1] for p in desired], label="desired", linewidth=1.0)
    axes[0][0].set_title("XY Trajectory")
    axes[0][0].set_xlabel("x [m]")
    axes[0][0].set_ylabel("y [m]")
    axes[0][0].axis("equal")
    axes[0][0].grid(True)
    axes[0][0].legend()

    if t and e3d:
        axes[0][1].plot(t[:len(e3d)], e3d, label="3D")
        axes[0][1].plot(t[:len(exy)], exy, label="XY")
        axes[0][1].plot(t[:len(ez_abs)], ez_abs, label="|Z|")
    axes[0][1].set_title("Tracking Error")
    axes[0][1].set_xlabel("time [s]")
    axes[0][1].set_ylabel("error [m]")
    axes[0][1].grid(True)
    axes[0][1].legend()

    axes[1][0].plot([p[1] for p in actual], [p[2] for p in actual], label="actual z")
    if desired:
        axes[1][0].plot([p[1] for p in desired], [p[2] for p in desired], label="desired z")
    axes[1][0].set_title("Y-Z Profile")
    axes[1][0].set_xlabel("y [m]")
    axes[1][0].set_ylabel("z [m]")
    axes[1][0].grid(True)
    axes[1][0].legend()

    if t and desired:
        axes[1][1].plot(t, [p[2] for p in desired], label="desired z")
    axes[1][1].plot(
        [f(row, "time_rel") for row in rows if f(row, "time_rel") is not None],
        [f(row, "actual_z") for row in rows if f(row, "time_rel") is not None and f(row, "actual_z") is not None],
        label="actual z")
    axes[1][1].set_title("Altitude")
    axes[1][1].set_xlabel("time [s]")
    axes[1][1].set_ylabel("z [m]")
    axes[1][1].grid(True)
    axes[1][1].legend()

    fig.tight_layout()
    fig.savefig(plot_path, dpi=150)
    plt.close(fig)
    return plot_path, None


def analyze(path, out_dir=None):
    rows = read_rows(path)
    if out_dir is None:
        out_dir = os.path.dirname(os.path.abspath(path))
    if not os.path.isdir(out_dir):
        os.makedirs(out_dir)
    base = os.path.splitext(os.path.basename(path))[0]

    valid_rows = [r for r in rows if f(r, "error_3d") is not None]
    actual_points = [
        (f(r, "actual_x"), f(r, "actual_y"), f(r, "actual_z"))
        for r in rows
        if f(r, "actual_x") is not None and f(r, "actual_y") is not None and f(r, "actual_z") is not None
    ]
    desired_points = [
        (f(r, "desired_x"), f(r, "desired_y"), f(r, "desired_z"))
        for r in valid_rows
        if f(r, "desired_x") is not None and f(r, "desired_y") is not None and f(r, "desired_z") is not None
    ]
    t0 = f(rows[0], "time_rel") if rows else 0.0
    t1 = f(rows[-1], "time_rel") if rows else 0.0
    summary = {
        "source_csv": os.path.abspath(path),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
        "samples_total": len(rows),
        "samples_with_desired": len(valid_rows),
        "duration_s": max(0.0, (t1 or 0.0) - (t0 or 0.0)),
        "actual_path_length_m": path_length(actual_points),
        "desired_path_length_m": path_length(desired_points),
        "error_3d": stats([f(r, "error_3d") for r in valid_rows if f(r, "error_3d") is not None]),
        "error_xy": stats([f(r, "error_xy") for r in valid_rows if f(r, "error_xy") is not None]),
        "abs_error_z": stats([abs(f(r, "error_z")) for r in valid_rows if f(r, "error_z") is not None]),
        "cmd_age": stats([f(r, "cmd_age") for r in valid_rows if f(r, "cmd_age") is not None]),
    }

    json_path, txt_path = write_summary(summary, out_dir, base)
    plot_path, plot_warning = make_plots(rows, out_dir, base)
    summary["summary_json"] = json_path
    summary["summary_txt"] = txt_path
    summary["plot_png"] = plot_path
    summary["plot_warning"] = plot_warning
    with open(json_path, "w") as fp:
        json.dump(summary, fp, indent=2, sort_keys=True)
    return summary


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("csv", help="trajectory CSV generated by trajectory_logger.py")
    parser.add_argument("--out-dir", default=None, help="analysis output directory")
    args = parser.parse_args()

    summary = analyze(args.csv, args.out_dir)
    print("samples_total=%d" % summary["samples_total"])
    print("samples_with_desired=%d" % summary["samples_with_desired"])
    print("duration_s=%.3f" % summary["duration_s"])
    print("error_3d_rmse=%.4f" % (summary["error_3d"]["rmse"] or float("nan")))
    print("error_3d_p95=%.4f" % (summary["error_3d"]["p95"] or float("nan")))
    print("error_3d_max=%.4f" % (summary["error_3d"]["max"] or float("nan")))
    print("summary_txt=%s" % summary["summary_txt"])
    if summary["plot_png"]:
        print("plot_png=%s" % summary["plot_png"])
    elif summary["plot_warning"]:
        print("plot_warning=%s" % summary["plot_warning"])


if __name__ == "__main__":
    main()
